using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Filters;

namespace Race_Day_Part_3_MVC.Filters
{
    public class MvcSessionAuthorizeAttribute : Attribute, IAsyncActionFilter
    {
        private readonly string? _requiredRole;

        public MvcSessionAuthorizeAttribute(string? requiredRole = null)
        {
            _requiredRole = requiredRole;
        }

        public async Task OnActionExecutionAsync(ActionExecutingContext context, ActionExecutionDelegate next)
        {
            var session = context.HttpContext.Session;
            var userId = session.GetString("UserId");
            var userRole = session.GetString("Role");

            // 1. If session identity keys are missing, return to Login gateway page
            if (string.IsNullOrEmpty(userId))
            {
                context.Result = new RedirectToActionResult("Login", "Account", null);
                return;
            }

            // 2. Perform case-insensitive matching validation on incoming role requests
            if (!string.IsNullOrEmpty(_requiredRole))
            {
                string normRequired = _requiredRole.Trim().ToLower();
                string normUserRole = (userRole ?? "Participant").Trim().ToLower();

                if (normUserRole != normRequired)
                {
                    context.Result = new RedirectToActionResult("AccessDenied", "Account", null);
                    return;
                }
            }

            await next();
        }
    }
}
